import json
import os
import urllib.parse
import urllib.request
import math

BASE = "http://prices.internal/api/v1/price"


def get_price(sku: str) -> float:
    """Fetch the current price for *sku* from the pricing service."""
    # The service can be configured with a pricing key in deployments that
    # require authentication.  Do not bake credentials into the client.
    headers = {}
    key = os.environ.get("PRICING_KEY")
    if key:
        headers["X-Pricing-Key"] = key
    request = urllib.request.Request(
        f"{BASE}/{urllib.parse.quote(str(sku), safe='')}", headers=headers
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    """Return the sum of the live prices for the supplied SKUs."""
    return math.fsum(get_price(sku) for sku in skus)
PY
