    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    """Return the total of the current prices for the supplied SKUs."""
    total = 0.0
    for sku in skus:
        total += get_price(sku)
    return total
